package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.period.ClosedPeriods;
import net.officefloor.hq.app.period.PeriodClosedException;
import net.officefloor.hq.app.person.People;
import net.officefloor.hq.app.person.PersonRetiredException;
import net.officefloor.hq.app.settings.Role;
import net.officefloor.hq.app.settings.Settings;
import net.officefloor.hq.app.sheet.Sheets;
import net.officefloor.plugin.variable.Val;

/** A steward re-dates an OPEN or PENDING claim. Its due-by stays as it was fixed and a figure a
 *  statement bound stays bound; so does its period (the one containing its due-by) and its number.
 *  Refused: anyone but a steward, a claim not OPEN or PENDING, a claim due by in a closed period,
 *  or a new date after its person's retirement. */
public class ApplyClaimRedate {
    public void apply(@Val ClaimRedate change, @Val Claim claim, People people, Settings settings, Sheets sheets,
            ClosedPeriods closedPeriods)
            throws ClaimStatusRefusedException, PeriodClosedException, PersonRetiredException {
        String sheetId = claim.getSheetId();
        if (sheets.archived(sheetId) || settings.role(sheetId, change.user()) != Role.STEWARD) {
            throw new ClaimStatusRefusedException("Only a steward can re-date a claim");
        }
        if (!claim.getStatus().isOpen()) {
            throw new ClaimStatusRefusedException("Only an OPEN or PENDING claim can be re-dated");
        }
        closedPeriods.refuse(sheetId, claim.getDueBy());
        people.find(sheetId, claim.getPersonId()).refuseRetired(change.date());
        change.redated(claim.getDate());
        claim.setDate(change.date());
    }
}
package net.officefloor.hq.app.claim;

import java.time.LocalDate;

/** A validated re-dating: the claim's new date and who re-dates it; `old` is the date it had, set once it is applied. */
public class ClaimRedate {
    private final LocalDate date;
    private final String user;
    private LocalDate old;

    public ClaimRedate(LocalDate date, String user) {
        this.date = date;
        this.user = user;
    }

    public LocalDate date() {
        return date;
    }

    public String user() {
        return user;
    }

    public LocalDate old() {
        return old;
    }

    public void redated(LocalDate old) {
        this.old = old;
    }
}
package net.officefloor.hq.app.claim;

/** Body of a re-dating: the claim's new date (yyyy-mm-dd), and who re-dates it. */
public record ClaimRedateRequest(String date, String user) {
}
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.person.People;
import net.officefloor.hq.app.person.Person;
import net.officefloor.plugin.variable.Val;

/** Runs after the claim is saved, so a refused re-dating writes no audit line. */
public class RecordClaimRedated {
    public void record(@Val ClaimRedate change, @Val Claim claim, People people, Audit audit) {
        Person person = people.find(claim.getSheetId(), claim.getPersonId());
        audit.record("CLAIM_REDATED sheet=" + claim.getSheetId() + " by=" + change.user()
                + " person=" + person.getName() + " amount=" + claim.getAmount().toPlainString()
                + " date=" + claim.getDate() + (claim.getNumber() != null ? " number=" + claim.getNumber() : "")
                + " old=" + change.old() + " new=" + change.date());
    }
}
package net.officefloor.hq.app.claim;

import java.time.LocalDate;
import java.time.format.DateTimeParseException;
import net.officefloor.hq.app.rollup.Actor;
import net.officefloor.hq.app.sheet.InvalidSheetRequestException;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

public class ValidateClaimRedate {
    public void validate(@RequestBody ClaimRedateRequest request, Out<ClaimRedate> body, Out<Actor> actor)
            throws InvalidSheetRequestException {
        String raw = request == null || request.date() == null ? "" : request.date().trim();
        try {
            actor.set(new Actor(request.user()));
            body.set(new ClaimRedate(LocalDate.parse(raw), request.user()));
        } catch (DateTimeParseException e) {
            throw new InvalidSheetRequestException("Not a date (yyyy-mm-dd): " + raw);
        }
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.plugin.variable.Val;

public class SaveClaim {
    public void save(@Val Claim claim, Claims claims) {
        claims.save(claim);
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.PathVariable;

public class LoadClaim {
    public void load(@PathVariable("sheetId") String sheetId, @PathVariable("claimId") long claimId,
            Claims claims, Out<Claim> claimOut) throws ClaimNotFoundException {
        Claim claim = claims.find(sheetId, claimId);
        if (claim == null) throw new ClaimNotFoundException(claimId);
        claimOut.set(claim);
    }
}
package net.officefloor.hq.app.rollup;

import net.officefloor.plugin.variable.Val;

/** Runs after the change's own audit lines: audits the figures it moved. */
public class RecordRollup {
    public void record(@Val RollupBefore before, @Val Actor actor, Rollup rollup) {
        rollup.record(before.sheetId(), before.snapshot(), actor.user());
    }
}
package net.officefloor.hq.app.rollup;

import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.PathVariable;

/** Runs before the change: keeps the sheet's figures as they were. */
public class SnapshotRollup {
    public void snapshot(@PathVariable("sheetId") String sheetId, Rollup rollup, Out<RollupBefore> before) {
        before.set(new RollupBefore(sheetId, rollup.snapshot(sheetId)));
    }
}

